"""Build the CMS email draft (to Head) .robot files from data/testcases_email_head.csv.

Run:  python tools/csv_to_robot_email_head.py [path/to/testcases_email_head.csv]

* Same idea as tools/csv_to_robot_dashboard.py: the CSV is the source of truth for ID, description,
  expected result and type. STEPS maps each ID to its keywords and file group.
* Writes tests/email_head/*.robot (the other test folders are not touched).
* Do not hand-edit the generated files; edit STEPS or resources/pages/email_head.resource instead.
"""
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from csv_to_robot import read_cases, render_test  # noqa: E402

ROOT = Path(__file__).resolve().parent.parent
DEFAULT_CSV = ROOT / "data" / "testcases_email_head.csv"
OUT_DIR = ROOT / "tests" / "email_head"
PREFIX = "EH"

GROUPS = {
    "open": ("01_open", "Open the draft, top of the page and wrong ids"),
    "form": ("02_form", "The form: default text, boxes and labels"),
    "attach": ("03_attachments", "CV attachment and the PDF preview"),
    "summary": ("04_info_status", "Info panel and status after sending"),
    "validation": ("05_validation", "Refused forms (nothing is sent)"),
    "layout": ("06_keyboard_layout", "Keyboard and screen sizes"),
}
MANUAL_FILE = "99_manual"

# EH id -> (group, [steps])
STEPS = {
    "EH001": ("open", ["Draft Should Open From The Profile"]),
    "EH002": ("open", ["Draft Heading And Subtitle Should Match"]),
    "EH003": ("open", ["Top Bar Should Show Brand And User", "Menu Texts Should Match"]),
    "EH004": ("open", ["Link Should Return To The Profile    ${ED_BACK_LINK}    ${ED_BACK_TEXT}"]),
    "EH005": ("open", ["Link Should Return To The Profile    ${ED_CANCEL}    ${ED_CANCEL_TEXT}"]),
    "EH006": ("open", ["Draft Should Ask For Login When Logged Out"]),
    "EH007": ("open", ["Unknown Applicant Draft Should Show Not Found    ${PF_FAKE_ID}"]),
    "EH008": ("open", ["Unknown Applicant Draft Should Show Not Found    ${PF_BAD_ID}"]),
    "EH009": ("open", ["Other Draft Types Should Open The Head Draft"]),
    "EH010": ("open", ["Refresh Should Keep The Same Draft"]),
    "EH011": ("form", ["Form Section Should Be Titled"]),
    "EH012": ("form", ["Form Labels Should Match"]),
    "EH013": ("form", ["Recipient Boxes Should Start Empty"]),
    "EH014": ("form", ["Every Draft Should Pass    subject"]),
    "EH015": ("form", ["Every Draft Should Pass    body_details"]),
    "EH016": ("form", ["Every Draft Should Pass    body_frame"]),
    "EH017": ("form", ["Boxes Should Be Editable"]),
    "EH018": ("form", ["Clicking A Label Should Focus Its Box"]),
    "EH019": ("form", ["Every Draft Should Pass    opens"]),
    "EH020": ("form", ["Every Draft Should Pass    title"]),
    "EH021": ("attach", ["Attachment Section Should Be Titled"]),
    "EH022": ("attach", ["Every Draft Should Pass    attachment"]),
    "EH023": ("attach", ["Draft Preview Should Show The CV"]),
    "EH024": ("attach", ["Draft Preview Should Close"]),
    "EH025": ("summary", ["Info Panel Should Be Titled"]),
    "EH026": ("summary", ["Every Draft Should Pass    info"]),
    "EH027": ("summary", ["Status After Sending Should Be Shown"]),
    "EH028": ("summary", ["Every Draft Should Pass    status_after"]),
    "EH029": ("summary", ["Status After Sending Should Match The Profile List"]),
    "EH030": ("summary", ["Every Draft Should Pass    target_status"]),
    "EH031": ("summary", ["Turning Off The Status Update Should Be Remembered"]),
    "EH032": ("summary", ["Send Buttons Should Be Ready"]),
    "EH033": ("validation", ["Empty To Should Be Refused"]),
    "EH034": ("validation", ["Spaces Only To Should Be Refused"]),
    "EH035": ("validation", ["Wrong To Should Be Refused"]),
    "EH036": ("validation", ["Empty Subject Should Be Refused"]),
    "EH037": ("validation", ["Empty Body Should Be Refused"]),
    "EH038": ("validation", ["Wrong Cc Should Be Flagged"]),
    "EH039": ("validation", ["Boxes Should Keep What Was Typed After A Refusal"]),
    "EH040": ("layout", ["Draft Tab Order Should Follow The Page"]),
    "EH041": ("layout", ["Info Panel Should Sit Beside The Form"]),
    "EH042": ("layout", ["Info Panel Should Sit Below The Form    768    1024"]),
    "EH043": ("layout", ["Page Should Not Scroll Sideways    375    812"]),
}

# Behaviour read from the dev site (or an expectation of mine) that the team must confirm.
ASSUMPTION_IDS = {"EH009", "EH013", "EH030", "EH038", "EH039", "EH040", "EH041", "EH042"}


def file_header(title, ids, manual=False):
    out = ["*** Settings ***",
           f"Documentation     {title} ({ids[0]} to {ids[-1]}). GENERATED by tools/csv_to_robot_email_head.py - do not edit."]
    if manual:
        out += ["Test Tags         manual"]
    else:
        out += ["Resource          ../../resources/all_pages.resource",
                "Suite Setup       Open Draft Browser",
                "Suite Teardown    Close All Browsers",
                "Test Setup        Open Draft",
                "Test Tags         automate    email-head    needs-account"]
    return "\n".join(out) + "\n\n\n*** Test Cases ***\n"


def main():
    csv_path = Path(sys.argv[1]) if len(sys.argv) > 1 else DEFAULT_CSV
    cases = read_cases(csv_path, PREFIX)
    auto = [c for c in cases if c["type"] == "automate"]
    manual = [c for c in cases if c["type"] == "manual"]

    missing = [c["id"] for c in auto if c["id"] not in STEPS]
    extra = [i for i in STEPS if i not in {c["id"] for c in auto}]
    if missing or extra:
        sys.exit(f"STEPS mismatch. In CSV as automate but no steps: {missing}. Steps but not automate in CSV: {extra}")

    OUT_DIR.mkdir(parents=True, exist_ok=True)
    for old in OUT_DIR.glob("*.robot"):
        old.unlink()

    by_group = {g: [] for g in GROUPS}
    for case in auto:
        group, steps = STEPS[case["id"]]
        tags = [case["id"], group]
        if case["id"] in ASSUMPTION_IDS:
            tags.append("assumption")
        by_group[group].append(render_test(case, steps, tags))

    for group, (filename, title) in GROUPS.items():
        tests = by_group[group]
        ids = [t.split()[0] for t in tests]
        body = file_header(title, ids) + "\n\n".join(tests) + "\n"
        (OUT_DIR / f"{filename}.robot").write_text(body, encoding="utf-8", newline="\n")

    manual_tests = [
        render_test(c, ["Skip    Manual case: run by hand and record the result in the CSV"], [c["id"], "manual"])
        for c in manual
    ]
    ids = [c["id"] for c in manual]
    body = file_header("Manual cases (always skipped)", ids, manual=True) + "\n\n".join(manual_tests) + "\n"
    (OUT_DIR / f"{MANUAL_FILE}.robot").write_text(body, encoding="utf-8", newline="\n")

    print(f"automate: {len(auto)}  manual: {len(manual)}  total: {len(cases)}")
    for group, (filename, _) in GROUPS.items():
        print(f"  email_head/{filename}.robot  {len(by_group[group])}")
    print(f"  email_head/{MANUAL_FILE}.robot  {len(manual)}")


if __name__ == "__main__":
    main()
